#pragma once

// Entry checks of gui_forms::TabControl, generated by tools/ic_declarations.py from
// include/gui_forms/controls/tab_control.ic.toml; edit the declaration, not this file. Each predicate is one `requires`
// clause of the declaration, so the condition the header states and the check the code runs are one text
// (docs/ic_declarations.md in template_harness).

#include "gui_forms/controls/tab_control.hpp"

namespace gui_forms::detail::ic::tab_control {

// TabControl::item_size: finite(incoming.width) and finite(incoming.height) and incoming.width >= 24 and
// incoming.height >= 18 and incoming.width <= item_extent_most and incoming.height <= item_extent_most; else failure
// invalid_argument.
[[nodiscard]] constexpr bool admits_item_size(const Size incoming) noexcept {
    const bool result = __builtin_isfinite(incoming.width)
                     && __builtin_isfinite(incoming.height)
                     && (incoming.width >= 24)
                     && (incoming.height >= 18)
                     && (incoming.width <= PageItemWidths::maximum_width)
                     && (incoming.height <= PageItemWidths::maximum_width);
    return result;
}

} // namespace gui_forms::detail::ic::tab_control
